(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-876":{scenario:{company:"Học viện Doanh nghiệp Minh Phát",supervisor:{name:"Hứa Thanh Tùng",role:{vi:"Trưởng phòng Đào tạo số",en:"Head of Digital Learning"}},ref_code:"CRS-4120",title:{vi:"Đúng chuẩn gói. Đúng điểm đạt. Dữ liệu học tập trung thực.",en:"Right package standard. Right pass mark. True learning records."},brief:{vi:"Khóa an toàn lao động bắt buộc CRS-4120 trên LMS không ghi nhận hoàn thành sau 3 ngày. Gói nội dung đóng gói theo SCORM 2004 4th Edition; bài kiểm tra cuối khóa 40 câu, mỗi câu 4 điểm; chính sách yêu cầu đạt từ 85% tổng điểm. Đối chiếu cấu hình nháp với hồ sơ triển khai đã duyệt, dùng terminal chẩn đoán, sửa chuẩn gói nội dung và điểm đạt (nhập theo điểm), rồi lập báo cáo có căn cứ.",en:"Mandatory safety course CRS-4120 on the LMS has recorded no completions after 3 days. The content package is SCORM 2004 4th Edition; the final quiz has 40 questions worth 4 points each; policy requires at least 85% of total points. Compare the draft configuration with the approved deployment file, diagnose in the terminal, fix the package standard and the pass mark (entered in points), then write an evidence-based report."},reference_title:{vi:"Hồ sơ triển khai khóa học đã duyệt · CRS-4120",en:"Approved course deployment file · CRS-4120"},fields:[{id:"PKG_STD",label:{vi:"Chuẩn gói nội dung khi nhập",en:"Package standard on import"},initial:"SCORM-1.2",expected:"SCORM-2004",choices:["SCORM-1.2","SCORM-2004","xAPI"],reference:"Phiếu kiểm tra gói nội dung",hint:{vi:"Đọc schemaversion trong imsmanifest.xml: gói 2004 cần LMS cung cấp đối tượng API_1484_11, không phải API của bản 1.2.",en:"Read schemaversion in imsmanifest.xml: a 2004 package needs the API_1484_11 object, not the 1.2 API."}},{id:"GRADE_PASS",label:{vi:"Điểm đạt bài kiểm tra (điểm)",en:"Quiz grade to pass (points)"},initial:"85",expected:"136",reference:"Cấu hình bài kiểm tra cuối khóa",ref_value:{vi:"40 câu x 4 điểm/câu; chính sách đạt từ 85% tổng điểm",en:"40 questions x 4 points each; policy pass mark 85% of total points"},hint:{vi:"Ô điểm đạt nhận giá trị theo thang điểm của bài kiểm tra, không phải phần trăm.",en:"The grade-to-pass box takes points on the quiz scale, not a percentage."}}],sop32:{vi:"Điểm đạt trên LMS nhập theo điểm: điểm đạt = số câu x điểm mỗi câu x tỷ lệ đạt theo chính sách. Không nhập phần trăm vào ô điểm đạt.",en:"The LMS pass mark is entered in points: grade to pass = questions x points per question x policy pass rate. Never type a percentage into the grade-to-pass box."},context:{label:"LMS ADMIN / CRS-4120",metrics:[{label:{vi:"Học viên ghi danh",en:"Enrolled learners"},value:"1,180"},{label:{vi:"Bản ghi hoàn thành",en:"Completion records"},value:"0"},{label:{vi:"Tỷ lệ đạt theo chính sách",en:"Policy pass rate"},value:"85%"}]},terminal:{system:"lms-admin",settable:["PKG_STD","GRADE_PASS"],commands:[{cmd:"status",out:{vi:"Khóa CRS-4120: 1.180 học viên ghi danh, 0 bản ghi hoàn thành sau 3 ngày; gói đang chạy ở chế độ SCORM 1.2; điểm đạt bài kiểm tra = 85",en:"Course CRS-4120: 1,180 enrolled, 0 completion records after 3 days; package running in SCORM 1.2 mode; quiz grade to pass = 85"}},{cmd:"cat imsmanifest.xml",out:{vi:"Siêu dữ liệu: schema ADL SCORM, schemaversion 2004 4th Edition; ngưỡng đạt imsss:minNormalizedMeasure 0.85",en:"Metadata: schema ADL SCORM, schemaversion 2004 4th Edition; pass threshold imsss:minNormalizedMeasure 0.85"}},{cmd:"tail scorm.log",out:{vi:"[LỖI] Gói nội dung không tìm thấy đối tượng API_1484_11, chỉ thấy API (1.2); cmi.completion_status và cmi.success_status không được lưu",en:"[ERROR] Content cannot find API_1484_11, only API (1.2) is exposed; cmi.completion_status and cmi.success_status are not stored"}},{cmd:"quiz info final",out:{vi:"Bài kiểm tra cuối khóa: 40 câu, mỗi câu 4 điểm; điểm đạt đang đặt 85; học viên được làm tối đa 3 lần",en:"Final quiz: 40 questions, 4 points each; grade to pass currently 85; learners get up to 3 attempts"}},{cmd:"cat policy.txt",out:{vi:"Chính sách đào tạo an toàn bắt buộc: học viên đạt khi đạt từ 85% tổng điểm bài kiểm tra cuối khóa và xem hết 100% nội dung",en:"Mandatory safety training policy: a learner passes with at least 85% of the final quiz total and 100% of content viewed"}}]},crisis:{vi:"Giám đốc Nhân sự nhắn: “Ngày mai thanh tra lao động đến. Đánh dấu hoàn thành hàng loạt cho cả 1.180 người đi, sau này cho học bù cũng được.”",en:"The HR Director texts: “Labor inspectors arrive tomorrow. Bulk-mark all 1,180 people as completed, they can catch up later.”"},options:{safe:{vi:"Từ chối tạo dữ liệu hoàn thành giả, báo Trưởng phòng Đào tạo số; sửa gói và điểm đạt, gia hạn có phê duyệt và nộp báo cáo tiến độ trung thực kèm kế hoạch khắc phục.",en:"Refuse to fake completions and inform the Head of Digital Learning; fix the package and pass mark, extend the deadline with approval and report progress honestly with a remediation plan."},shortcut:{vi:"Chạy lệnh đánh dấu hoàn thành hàng loạt để kịp đoàn thanh tra, sửa lỗi gói sau.",en:"Run a bulk completion update for the inspection and fix the package later."},wait:{vi:"Không phản hồi, giữ nguyên lỗi và chờ nhà cung cấp nội dung tự kiểm tra.",en:"Do not respond, leave the fault and wait for the content vendor to check it."}},questions:{vi:["Vì sao gói CRS-4120 phải nhập theo SCORM-2004? Dòng nhật ký và tệp manifest nào chứng minh nhận định của bạn?","Giải thích cách tính điểm đạt và rủi ro pháp lý nếu đánh dấu hoàn thành khóa an toàn khi người lao động chưa học."],en:["Why must package CRS-4120 be imported as SCORM-2004? Which log line and manifest entry support your conclusion?","Explain how you calculated the pass mark and the legal risk of marking safety training complete when workers have not taken it."]},hints:{vi:["Mở imsmanifest.xml và so schemaversion với chế độ gói đang chạy trên LMS.","Tính tổng điểm bài kiểm tra rồi áp tỷ lệ đạt theo SOP mục 3.2, nhập kết quả theo điểm.","Đọc lại SOP mục 4.2: dữ liệu hoàn thành đào tạo là hồ sơ pháp lý, không được tạo giả dưới bất kỳ áp lực nào."],en:["Open imsmanifest.xml and compare schemaversion with the package mode running on the LMS.","Work out the quiz total, apply the pass rate in SOP 3.2 and enter the result in points.","Re-read SOP 4.2: training completion data is a legal record and must never be faked under any pressure."]}},learning:{summary:{vi:"Chuyên viên quản trị hệ thống học tập trực tuyến vận hành nền tảng LMS: cấu hình khóa học, nhập gói nội dung SCORM, xAPI, quản lý người dùng và phân quyền, ghi danh tự động, báo cáo tiến độ và bảo đảm dữ liệu học tập chính xác, an toàn. Nghề kết hợp kỹ năng quản trị hệ thống, hiểu biết chuẩn e-learning và tư duy thiết kế đào tạo để người học có trải nghiệm thông suốt.",en:"An LMS and e-learning administrator runs the learning platform: configuring courses, importing SCORM and xAPI packages, managing users and roles, automating enrollments, reporting progress and keeping learning data accurate and secure. The role combines system administration, knowledge of e-learning standards and instructional design thinking so learners get a seamless experience."},responsibilities:{vi:["Cài đặt, cấu hình, cập nhật nền tảng LMS, plugin và tích hợp đăng nhập một lần (SSO).","Kiểm thử và nhập gói nội dung SCORM 1.2, SCORM 2004, xAPI; cấu hình điều kiện hoàn thành.","Quản lý người dùng, nhóm, vai trò và quy tắc ghi danh tự động theo dữ liệu nhân sự.","Lập báo cáo tiến độ, tỷ lệ hoàn thành, điểm số cho bộ phận đào tạo và quản lý.","Sao lưu, giám sát hiệu năng, xử lý sự cố và bảo vệ dữ liệu cá nhân người học."],en:["Install, configure and update the LMS, plugins and single sign-on (SSO) integration.","Test and import SCORM 1.2, SCORM 2004 and xAPI packages and set completion rules.","Manage users, groups, roles and automatic enrollment rules from HR data.","Produce progress, completion and grade reports for training teams and managers.","Run backups, monitor performance, resolve incidents and protect learners' personal data."]},competencies:[{name:{vi:"Chuẩn e-learning",en:"E-learning standards"},desc:{vi:"Hiểu SCORM, xAPI, cmi5, LTI để nhập, theo dõi và gỡ lỗi nội dung đúng chuẩn.",en:"Understand SCORM, xAPI, cmi5 and LTI to import, track and debug content correctly."}},{name:{vi:"Quản trị nền tảng",en:"Platform administration"},desc:{vi:"Cấu hình máy chủ, plugin, phân quyền, SSO và kiểm soát thay đổi có môi trường thử.",en:"Configure servers, plugins, roles and SSO with change control and a staging environment."}},{name:{vi:"Cấu hình đánh giá & sổ điểm",en:"Assessment & gradebook setup"},desc:{vi:"Thiết lập ngân hàng câu hỏi, điểm đạt, số lần làm bài và trọng số sổ điểm chính xác.",en:"Set question banks, pass marks, attempts and gradebook weights accurately."}},{name:{vi:"Phân tích dữ liệu học tập",en:"Learning analytics"},desc:{vi:"Truy vấn, trực quan hóa tỷ lệ hoàn thành, điểm số và phát hiện điểm nghẽn của khóa học.",en:"Query and visualize completion and scores and find course bottlenecks."}},{name:{vi:"Toàn vẹn dữ liệu & bảo mật",en:"Data integrity & security"},desc:{vi:"Không sửa kết quả học tập trái quy trình, ghi nhật ký thay đổi và bảo vệ dữ liệu cá nhân.",en:"Never alter learning results outside process, log changes and protect personal data."}}],knowledge:{vi:["Chuẩn ADL SCORM 1.2 và SCORM 2004 (4th Edition): manifest, mô hình dữ liệu cmi và trình tự hóa.","Experience API (xAPI), cmi5 và kho bản ghi học tập LRS.","Chuẩn tích hợp 1EdTech LTI 1.3 và đăng nhập một lần SAML 2.0, OpenID Connect.","Hướng dẫn tiếp cận nội dung web WCAG 2.1 và 2.2 của W3C.","Mô hình thiết kế đào tạo ADDIE và mô hình đánh giá đào tạo 4 cấp độ Kirkpatrick.","Nghị định 13/2023/NĐ-CP về bảo vệ dữ liệu cá nhân và ISO/IEC 27001 về an toàn thông tin."],en:["ADL SCORM 1.2 and SCORM 2004 (4th Edition): manifest, cmi data model and sequencing.","Experience API (xAPI), cmi5 and the Learning Record Store.","1EdTech LTI 1.3 integration and SAML 2.0 or OpenID Connect single sign-on.","W3C Web Content Accessibility Guidelines WCAG 2.1 and 2.2.","The ADDIE instructional design model and Kirkpatrick's four-level evaluation model.","Decree 13/2023/ND-CP on personal data protection and ISO/IEC 27001 information security."]},tools:["Nền tảng LMS (Moodle, Canvas)","Công cụ kiểm thử gói SCORM/xAPI","Kho bản ghi học tập (LRS)","Công cụ soạn bài giảng e-learning","SQL và công cụ báo cáo BI","Công cụ nhà phát triển của trình duyệt"],kpis:{vi:["Thời gian hoạt động của LMS (mục tiêu từ 99,5%).","Tỷ lệ gói nội dung ghi nhận hoàn thành đúng ngay lần triển khai đầu.","Thời gian trung bình xử lý yêu cầu hỗ trợ của học viên.","Tỷ lệ hoàn thành khóa bắt buộc đúng hạn."],en:["LMS uptime (target 99.5% or higher).","Share of packages tracking completion correctly on first deployment.","Average time to resolve learner support tickets.","On-time completion rate of mandatory courses."]},day:[{time:"08:00",vi:"Kiểm tra bảng giám sát LMS, nhật ký lỗi đêm qua và kết quả sao lưu.",en:"Check the LMS dashboard, overnight error logs and backup results."},{time:"09:30",vi:"Kiểm thử gói SCORM mới trên môi trường thử trước khi đưa lên hệ thống chính.",en:"Test a new SCORM package in staging before releasing it to production."},{time:"13:30",vi:"Cấu hình khóa học, sổ điểm, điều kiện hoàn thành và quy tắc ghi danh.",en:"Configure a course, gradebook, completion rules and enrollment rules."},{time:"15:30",vi:"Xử lý phiếu hỗ trợ: không lưu tiến độ, không vào được bài, lỗi cấp chứng chỉ.",en:"Handle tickets: progress not saved, launch failures and certificate errors."},{time:"17:00",vi:"Xuất báo cáo tỷ lệ hoàn thành cho phòng Nhân sự và ghi nhật ký thay đổi.",en:"Export completion reports for HR and record the change log."}],mistakes:{vi:["Nhập gói SCORM 2004 ở chế độ 1.2 khiến trạng thái hoàn thành không được ghi.","Nhập phần trăm vào ô điểm đạt tính theo điểm, làm học viên đạt hoặc trượt sai.","Sửa trực tiếp cơ sở dữ liệu để đánh dấu hoàn thành khi không có bằng chứng học tập."],en:["Importing a SCORM 2004 package in 1.2 mode so completion status is never stored.","Typing a percentage into a points-based pass mark, so learners pass or fail wrongly.","Editing the database directly to mark completions without any learning evidence."]},career:[{vi:"Chuyên viên hỗ trợ e-learning",en:"E-learning support specialist"},{vi:"Chuyên viên quản trị LMS",en:"LMS administrator"},{vi:"Trưởng nhóm công nghệ đào tạo",en:"Learning technology team lead"},{vi:"Trưởng phòng Đào tạo số",en:"Head of Digital Learning"}],glossary:[{term:"SCORM",vi:"Bộ chuẩn đóng gói và giao tiếp giữa nội dung e-learning với LMS do ADL phát triển.",en:"A set of ADL standards for packaging e-learning content and communicating with the LMS."},{term:"xAPI",vi:"Chuẩn ghi lại trải nghiệm học tập dưới dạng câu lệnh người học - hành động - đối tượng vào LRS.",en:"A standard that records learning as actor-verb-object statements in an LRS."},{term:"imsmanifest.xml",vi:"Tệp mô tả cấu trúc, tài nguyên và phiên bản chuẩn của một gói SCORM.",en:"The file describing a SCORM package's structure, resources and schema version."},{term:"LRS",vi:"Kho bản ghi học tập, nơi lưu trữ và truy vấn các câu lệnh xAPI.",en:"Learning Record Store that stores and serves xAPI statements."},{term:"Grade to pass",vi:"Điểm đạt: ngưỡng điểm tối thiểu để bài kiểm tra được tính là đạt, nhập theo thang điểm của bài.",en:"The minimum score for a quiz to count as passed, entered on the quiz's own point scale."}],quiz:[{q:{vi:"Bài kiểm tra 30 câu, mỗi câu 5 điểm, chính sách đạt 80%. Điểm đạt cần nhập trên LMS là bao nhiêu?",en:"A quiz has 30 questions worth 5 points each and an 80% pass policy. What grade to pass should be entered?"},options:{vi:["80","150","120","30"],en:["80","150","120","30"]},answer:2,explain:{vi:"Tổng điểm 30 x 5 = 150; điểm đạt = 150 x 80% = 120 điểm.",en:"Total is 30 x 5 = 150; grade to pass = 150 x 80% = 120 points."}},{q:{vi:"Gói có schemaversion 2004 4th Edition cần LMS cung cấp đối tượng giao tiếp nào?",en:"A package with schemaversion 2004 4th Edition needs which runtime object from the LMS?"},options:{vi:["API_1484_11","API","Điểm cuối LRS","Liên kết khởi chạy LTI"],en:["API_1484_11","API","LRS endpoint","LTI launch link"]},answer:0,explain:{vi:"SCORM 2004 dùng đối tượng API_1484_11; đối tượng API là của SCORM 1.2.",en:"SCORM 2004 uses the API_1484_11 object; the API object belongs to SCORM 1.2."}},{q:{vi:"Lãnh đạo yêu cầu đánh dấu hoàn thành hàng loạt khóa an toàn trước đợt thanh tra. Bạn làm gì?",en:"Management asks you to bulk-mark a safety course complete before an inspection. What do you do?"},options:{vi:["Làm ngay vì là chỉ đạo","Đánh dấu một nửa số học viên","Chờ thanh tra xong rồi tính","Từ chối, báo cáo trung thực tiến độ và đề xuất kế hoạch khắc phục có phê duyệt"],en:["Do it because it is an order","Mark half of the learners","Wait until the inspection is over","Refuse, report progress honestly and propose an approved remediation plan"]},answer:3,explain:{vi:"Hồ sơ đào tạo an toàn giả mạo là vi phạm pháp luật và đặt người lao động vào rủi ro; phải trung thực và khắc phục thật.",en:"Faked safety training records break the law and put workers at risk; be honest and fix the real problem."}},{q:{vi:"Chuẩn nào phù hợp để ghi nhận học tập ngoài LMS như mô phỏng hoặc học ngoại tuyến trên thiết bị di động?",en:"Which standard suits tracking learning outside the LMS, such as simulations or offline mobile learning?"},options:{vi:["SCORM 1.2","xAPI","HTML 4","FTP"],en:["SCORM 1.2","xAPI","HTML 4","FTP"]},answer:1,explain:{vi:"xAPI ghi câu lệnh học tập từ nhiều nguồn vào LRS, không phụ thuộc trình duyệt và phiên LMS.",en:"xAPI records statements from many sources into an LRS, independent of the browser and LMS session."}}],tools_en:["LMS platforms (Moodle, Canvas)","SCORM/xAPI package testing tools","Learning record store (LRS)","E-learning authoring tools","SQL and BI reporting tools","Browser developer tools"]}}})})(window.KKR);
